-- CREATE TABLE BANK_TRANSACTIONS (
--     TRANSACTION_ID NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
--     ACCOUNT_ID NUMBER NOT NULL REFERENCES BANK_ACCOUNTS(ACCOUNT_ID),
--     TRANSACTION_TYPE VARCHAR2(20) NOT NULL CHECK (TRANSACTION_TYPE IN ('DEPOSIT','WITHDRAWAL')),
--     AMOUNT NUMBER(15,2) NOT NULL CHECK (AMOUNT > 0),
--     DESCRIPTION VARCHAR2(250),
--     CREATED_AT TIMESTAMP DEFAULT SYSTIMESTAMP NOT NULL
-- );

CREATE OR REPLACE PROCEDURE deposit_money(
    p_account_id IN NUMBER,
    p_amount IN NUMBER
)
AS
BEGIN
    IF p_amount IS NULL OR p_amount <= 0 THEN
        RAISE_APPLICATION_ERROR(
            -20001,
            'Amount must be greater than zero'
        );
    END IF;

    UPDATE BANK_ACCOUNTS
    SET BALANCE = BALANCE + p_amount
    WHERE ACCOUNT_ID = p_account_id;

    IF SQL%ROWCOUNT = 0 THEN
        RAISE_APPLICATION_ERROR(
            -20002,
            'Account not found'
        );
    END IF;

    INSERT INTO BANK_TRANSACTIONS (
        ACCOUNT_ID,
        TRANSACTION_TYPE,
        AMOUNT,
        DESCRIPTION
    )
    VALUES (
        p_account_id,
        'DEPOSIT',
        p_amount,
        'Money deposited'
    );
END;
/


-- Query to know the procedure is created
-- SELECT OBJECT_NAME, STATUS
-- FROM USER_OBJECTS
-- WHERE OBJECT_NAME = 'DEPOSIT_MONEY'
--   AND OBJECT_TYPE = 'PROCEDURE';

--Procedure to insert record into BANK_TRANSACTIONS
CREATE OR REPLACE PROCEDURE withdraw_money(
    p_account_id IN NUMBER,
    p_amount IN NUMBER
)
AS
    v_balance BANK_ACCOUNTS.BALANCE%TYPE;
BEGIN
    -- Validate the withdrawal amount
    IF p_amount IS NULL OR p_amount <= 0 THEN
        RAISE_APPLICATION_ERROR(
            -20003,
            'Amount must be greater than zero'
        );
    END IF;

    -- Retrieve and lock the account balance
    SELECT BALANCE
    INTO v_balance
    FROM BANK_ACCOUNTS
    WHERE ACCOUNT_ID = p_account_id
    FOR UPDATE;

    -- Check available balance
    IF v_balance < p_amount THEN
        RAISE_APPLICATION_ERROR(
            -20004,
            'Insufficient funds'
        );
    END IF;

    -- Deduct the withdrawal amount
    UPDATE BANK_ACCOUNTS
    SET BALANCE = BALANCE - p_amount
    WHERE ACCOUNT_ID = p_account_id;

    -- Record the withdrawal
    INSERT INTO BANK_TRANSACTIONS (
        ACCOUNT_ID,
        TRANSACTION_TYPE,
        AMOUNT,
        DESCRIPTION
    )
    VALUES (
        p_account_id,
        'WITHDRAWAL',
        p_amount,
        'Money withdrawn'
    );

EXCEPTION
    WHEN NO_DATA_FOUND THEN
        RAISE_APPLICATION_ERROR(
            -20005,
            'Account not found'
        );
END;
/

--Check above procedure
SELECT OBJECT_NAME, STATUS FROM USER_OBJECTS
WHERE OBJECT_NAME IN('DEPOSIT_MONEY','WITHDRAW_MONEY')
AND OBJECT_TYPE = 'PROCEDURE'
ORDER BY OBJECT_NAME;

