SELECT
    t.TRANSACTION_ID,
    a.ACCOUNT_HOLDER,
    a.ACCOUNT_NUMBER,
    t.TRANSACTION_TYPE,
    t.AMOUNT,
    t.DESCRIPTION,
    t.CREATED_AT
FROM BANK_TRANSACTIONS t
JOIN BANK_ACCOUNTS a
    ON t.ACCOUNT_ID = a.ACCOUNT_ID
ORDER BY t.TRANSACTION_ID DESC;

